package ledger

import (
	"os"
	"testing"
)

func TestPrimary(t *testing.T) {
	var entries []int
	expected := 0
	switch os.Getenv("ORACLE_CASE_ID") {
	case "symptom":
		entries = []int{12, 30}
		expected = 42
	case "empty":
		entries = []int{}
	case "single":
		entries = []int{8}
		expected = 8
	default:
		t.Fatal("invalid case")
	}
	if got := Balance(entries); got != expected {
		t.Fatalf("ORACLE_ASSERTION[ticket_balance]: got %d expected %d", got, expected)
	}
}

independent:
package ledger

import (
	"os"
	"testing"
)

func TestIndependent(t *testing.T) {
	var ledgers [][]int
	switch os.Getenv("ORACLE_CASE_ID") {
	case "symptom":
		ledgers = [][]int{{12, 30}, {7, 10}}
	case "empty":
		ledgers = [][]int{{}}
	case "single":
		ledgers = [][]int{{8}}
	default:
		t.Fatal("invalid case")
	}
	for _, entries := range ledgers {
		remainder := Balance(entries)
		for _, credit := range entries {
			remainder -= credit
		}
		if remainder != 0 {
			t.Fatalf("ORACLE_ASSERTION[conservation]: remainder %d", remainder)
		}
	}
}

